package platform

import "runtime"

// NativeCapability reports the current platform's native capability,
// falling back to "stub" for unsupported platforms.
var NativeCapability = func() string {
	switch runtime.GOOS {
	case "linux", "darwin", "freebsd", "openbsd", "netbsd", "dragonfly", "solaris", "aix":
		return "native"
	default:
		return "stub"
	}
}()
